USE sentinel_ai_security;
CREATE TABLE IF NOT EXISTS incidents (
    incident_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, incident_uuid CHAR(36) NOT NULL, company_id BIGINT UNSIGNED NOT NULL, site_id BIGINT UNSIGNED NOT NULL, employee_id BIGINT UNSIGNED NULL, reporter_user_id BIGINT UNSIGNED NULL, shift_assignment_id BIGINT UNSIGNED NULL, patrol_session_id BIGINT UNSIGNED NULL,
    incident_number VARCHAR(80) NOT NULL, incident_type VARCHAR(100) NOT NULL, incident_category VARCHAR(100) NOT NULL, severity ENUM('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'LOW', status ENUM('OPEN','INVESTIGATING','RESOLVED','CLOSED','CANCELLED') NOT NULL DEFAULT 'OPEN', occurred_at DATETIME NOT NULL, reported_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    description TEXT NOT NULL, actions_taken TEXT NULL, resolution TEXT NULL, created_by_user_id BIGINT UNSIGNED NULL, updated_by_user_id BIGINT UNSIGNED NULL, closed_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL,
    CONSTRAINT fk_incidents_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, CONSTRAINT fk_incidents_site FOREIGN KEY (site_id) REFERENCES sites(site_id) ON DELETE RESTRICT, CONSTRAINT fk_incidents_employee FOREIGN KEY (employee_id) REFERENCES employees(employee_id) ON DELETE SET NULL, CONSTRAINT fk_incidents_reporter FOREIGN KEY (reporter_user_id) REFERENCES users(user_id) ON DELETE SET NULL, CONSTRAINT fk_incidents_shift FOREIGN KEY (shift_assignment_id) REFERENCES shift_assignments(shift_assignment_id) ON DELETE SET NULL, CONSTRAINT fk_incidents_patrol FOREIGN KEY (patrol_session_id) REFERENCES patrol_sessions(patrol_session_id) ON DELETE SET NULL, CONSTRAINT fk_incidents_created_by FOREIGN KEY (created_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL, CONSTRAINT fk_incidents_updated_by FOREIGN KEY (updated_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL,
    UNIQUE KEY uq_incidents_uuid (incident_uuid), UNIQUE KEY uq_incidents_company_number (company_id,incident_number), INDEX idx_incidents_company_status (company_id,status), INDEX idx_incidents_company_site (company_id,site_id), INDEX idx_incidents_company_occurred_at (company_id,occurred_at), INDEX idx_incidents_company_deleted_at (company_id,deleted_at)
);